// Initialize Explicit State with ASAAS Brand Tokens
const input = $input.first().json;
return [{
  json: {
    brand_name: input['اسم العلامة التجارية / الكيان (Brand Name)'] || 'شركة أساس للحلول الذكية',
    platform: input['المنصة المستهدفة (Platform)'] || 'LinkedIn (منشور مهني تحليلي رصين)',
    dialect: input['اللهجة ونبرة الصوت (Dialect & Tone)'] || 'عربية فصحى معاصرة رصينة (نبرة أساس المؤسسية)',
    target_audience: input['الجمهور المستهدف (Target Audience)'] || 'مدراء التحول الرقمي والتسويق التنفيذي',
    campaign_topic: input['فكرة الحملة أو المنشور (Campaign Topic / Angle)'] || 'مسارات أكاديمية أساس للذكاء الاصطناعي',
    iteration_count: 0,
    max_iterations: 2,
    tone_score: 0,
    critique_feedback: '',
    status: 'initialized',
    session_id: 'session_' + Date.now(),
    brand_tokens: {
      primary_gold: '#BA9555',
      ink: '#221F1F',
      sand: '#D3C6B4',
      typography: 'Thmanyah (ثمانية)',
      voice_rules: 'حاسم، مهني، مدعوم بالأرقام، خالي من الحشو الإنشائي'
    }
  }
}];

// ASAAS Brand Guidelines & Platform Adaptation
return JSON.stringify({
  "Typography": "الخط المعتمد: خط ثمانية (Thmanyah). العناوين بـ Thmanyah Serif Display، والنصوص والأرقام بـ Thmanyah Sans.",
  "Brand_Colors": "الذهبي الأساسي (#BA9555)، الأسود الحبري (#221F1F)، الرملي (#D3C6B4).",
  "Voice_Standard": "الكلمات العربية قصيرة ومباشرة، أفعال حاسمة، نبرة دافئة بدون تكلف أو حشو، الأرقام صريحة ودقيقة.",
  "Platform_Rules": {
    "LinkedIn": "فقرات قصيرة ومريحة للعين، حقائق وأرقام واضحة، 3 إلى 4 هاشتاقات احترافية، ودعوة لمشاركة الرأي في قطاع الأعمال.",
    "X_Twitter": "إيقاع حاد ومكثف، سطر افتتاحي صادم، تحت 280 حرف للمنشور الفردي، أو تقسيم منطقي لثريد.",
    "Instagram": "سرد بصري ملهم، عبارة افتتاحية عريضة، وتركيز على القيمة الإنسانية والعملية.",
    "Reels_TikTok": "سكريبت 60 ثانية يبدأ بـ Hook خاطف في أول 3 ثوان، ثم مقارنة ثنائية واضحة، وخاتمة بـ CTA مباشر."
  }
});

// Reflexion Loop Controller & Guardrail Logic
const orchestratorOutput = $('Orchestrator Agent').first().json.output || '';
const evalRaw = $input.first().json.text || '{}';

let evalJson = { tone_score: 8, verbal_feedback: 'متوافق تماماً مع معايير هوية أساس', is_passed: true };
try {
  const jsonMatch = evalRaw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    evalJson = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  evalJson = { tone_score: 8, verbal_feedback: evalRaw, is_passed: true };
}

const state = $('Initialize State & ASAAS Brand Tokens').first().json;
const currentIteration = (state.iteration_count || 0) + 1;
const maxIterations = state.max_iterations || 2;
const isApproved = (evalJson.tone_score >= 8) || (currentIteration >= maxIterations);

return [{
  json: {
    ...state,
    current_draft: orchestratorOutput,
    iteration_count: currentIteration,
    tone_score: evalJson.tone_score,
    critique_feedback: evalJson.verbal_feedback,
    is_approved: isApproved,
    stop_reason: isApproved ? (evalJson.tone_score >= 8 ? 'Quality_Threshold_Passed (>=8/10)' : 'Max_Iteration_Cap_Reached (2 Loops)') : 'Needs_Revision'
  }
}];
